import fs from 'node:fs';
import path from 'node:path';
import {root,out,save} from './collect.mjs';
import {PROCEDURES} from '../../backend/src/db/procedures.js';
const dir=path.dirname(out),read=n=>JSON.parse(fs.readFileSync(path.join(out,n),'utf8'));
const write=(name,body)=>fs.writeFileSync(path.join(dir,name),body);
const ev=n=>`[${n}](./evidence/${n})`;
const src=(file,needle)=>{if(!file)return '—';const s=fs.readFileSync(path.join(root,file),'utf8');const i=needle?s.indexOf(needle):-1;const line=i>=0?s.slice(0,i).split('\n').length:1;const target=`../../${file}#L${line}`;return `[${file}:${line}](${file.includes(' ')?'<'+target+'>':target})`;};
const table=(heads,rows)=>`| ${heads.join(' | ')} |\n| ${heads.map(()=> '---').join(' | ')} |\n${rows.map(r=>`| ${r.map(x=>String(x??'—').replaceAll('|','\\|').replaceAll('\n','<br>')).join(' | ')} |`).join('\n')}\n`;
const modules=read('complete-module-audit.json'),objects=read('live-objects.json'),columns=read('live-columns.json'),fks=read('live-foreign-keys.json'),checks=read('live-checks.json'),indexes=read('live-indexes.json'),fixtures=read('fixture-manifest.json'),chains=read('api-chain-inventory.json'),drift=read('module-drift.json');
const bugs=[];
function bug(id,title,severity,confidence,uc,layer,rule,expected,actual,steps,evidence,db,be,fe,rootCause,fix,tests,impact='Không chứng minh truy cập trái quyền.',data='Không chứng minh sửa dữ liệu cũ qua hành vi này.'){
 bugs.push({id,title,severity,confidence,uc,layer,rule,expected,actual,steps,evidence,db,be,fe,rootCause,fix,tests,impact,data});
}
