write('MODULE_AUDIT.md','# Complete SQL module audit\n\nInventory tất cả 154 deployed modules. `STATIC/PARTIAL` có nghĩa đã đọc contract/dependency, không chứng nhận mọi branch runtime. Signature capture 110 service methods là stub inspection, không phải real DB PASS. Legacy alias không có app caller chưa đủ để xóa.\n\n'+modules.map(m=>`## ${m.name}\n\n**Type / source sync:** ${m.type} / ${m.sourceStatus}; ${m.source?src(m.source):'DB ONLY'}\n\n**Parameters:** ${m.parameters.map(p=>`${p.name||'RETURN'} ${p.typeName}${/char/.test(p.typeName)?'('+ (p.max_length===-1?'MAX':p.typeName.startsWith('n')?p.max_length/2:p.max_length)+')':''}${p.is_output?' OUTPUT':''}`).join(', ')||'none'}\n\n**Dependencies:** ${m.references.join(', ')||'—'}\n\n**SQL callers:** ${m.callers.join(', ')||'—'}\n\n**Backend callers:** ${m.backendCallers.join(', ')||'—'}\n\n**Transaction / savepoint / TRY-CATCH / XACT_ABORT:** ${m.transaction} / ${m.savepoint} / ${m.tryCatch} / ${m.xactAbort}\n\n**Locks:** ${m.locks.join(', ')||'none explicit'}\n\n**THROW:** ${m.throwNumbers.join(', ')||'—'}\n\n**Verification:** ${m.verification}; ${m.multirowReview??'—'}\n`).join('\n'));
write('API_MATRIX.md','# API → Controller → Service → SP inventory\n\n118 endpoint; 117 có SP qua service/middleware hoặc DB-health. /health là liveness không gọi DB. Dependencies là trực tiếp; traversal đầy đủ trong MODULE_AUDIT. Cột guard gồm middleware dùng chung của router và handlers riêng từng endpoint.\n\n'+table(['Method / API','Guard / handlers','Controller','Validator','Service → SP','DB dependencies'],chains.map(c=>[`${c.method} ${c.path}`,(c.globalGuards??[]).join('; ')+'; '+c.handlers,c.controller,c.validators.join(', '),c.serviceMethods.join(', ')+' → '+c.procedures.join(', '),c.tablesAndDependencies.join(', ')])));
write('FIXTURE_MANIFEST.md','# Audit fixtures\n\nRun `mus0s7zc`; tạo bằng API/SP, không direct INSERT. Dữ liệu fixture được giữ lại để review. Một số fixture rỗng mới tạo đã được xóa qua API để kiểm DELETE; `deleted:true` chỉ các dòng của audit. Không tự cleanup dữ liệu cũ. Manifest machine-readable: '+ev('fixture-manifest.json')+'\n\n'+Object.entries(fixtures).filter(([,v])=>Array.isArray(v)).map(([n,rows])=>`## ${n}\n\n${table(['Entry','Details'],rows.map((r,i)=>[i+1,JSON.stringify(r)]))}`).join('\n'));
